-- Label compilations and live albums all get the artist 'Socks On Records' so the Releases filter can find them.
update public.releases set artist_text='Socks On Records' where lower(coalesce(artist_text,'')) in ('various artists','various','socks on records and friends','socks on records & friends') or bandcamp_url like 'https://socksonrecords.bandcamp.com/%' or lower(title) like 'music against living miserably%';
